from collections import deque


def find_path(grid, start, end):
    """Return the list of cells from start to end (inclusive) or None if unreachable."""
    rows, cols = len(grid), len(grid[0])
    parent = {start: None}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        if cur == end:
            break
        r, c = cur
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != "#" and (nr, nc) not in parent:
                parent[(nr, nc)] = cur
                queue.append((nr, nc))
    if end not in parent:
        return None
    path = []
    cur = end
    while cur != start:
        path.append(cur)
        cur = parent[cur]
    return path

